mapper.delete:
delete  from CHB_AST_VAL c


		DATE_FORMAT(c.VAL_DATE,'%Y-%m-%d') = #{valDate,jdbcType=VARCHAR}


		and c.STATUS  = #{status,jdbcType=VARCHAR}


		and  c.val_id  in  (select  d.val_id  from   CHB_AST_VAL d
		left join chb_asset_info_sub csb on csb.ASSET_CODE=d.ASSET_CODE
		LEFT JOIN CHB_ASSET_SUB_STATUS CS ON csb.REGIST_SEQNO=CS.REGIST_SEQNO AND CS.ASSET_TYPE='01'
		where CS.INSTITUTION_CODE =#{InstitutionCode,jdbcType=VARCHAR}
		)
